-- mod-devourer: every Devourer spell (server `spell_dbc`), script bindings, procs, the shape rows and the idols.
-- Written by tools/coa/build_devourer_spells.py (the client patch gets the same rows in Spell.dbc). The 64 rows
-- carried over from ChaosCore0.3 are unchanged; 9100050-9100069 are the placeholder talents. Safe to run again.

-- Generated by mod-devourer/tools/build_devourer_spells.py -- do not edit by hand.
DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 9100000 AND 9100899;

-- Script bindings.
DELETE FROM `spell_script_names` WHERE `spell_id` BETWEEN 9100000 AND 9100899;

-- Forms are put back by the module at login and after resurrection, never saved with the character.
DELETE FROM `spell_custom_attr` WHERE `spell_id` BETWEEN 9100000 AND 9100899;

-- Rain of Toads: 15% from Chain Lightning / Coil Strike (the script checks which), at most every 6 sec.
DELETE FROM `spell_proc` WHERE `SpellId` BETWEEN 9100000 AND 9100899;
    -- ChaosCore0.3: Teething chews on every landed attack; Meal: Grave heals from melee damage done.
    (9100408, 0, 0, 0, 0, 0, 20, 1, 2, 0, 0, 0, 100, 0, 0),
    (9100026, 0, 0, 0, 0, 0, 20, 1, 2, 0, 0, 0, 100, 0, 0);

-- Shapes: the form spell, the base look and the kit.
DELETE FROM `devourer_shape` WHERE `shape_id` IN (1, 2, 3, 4);

-- Until Sethrak can be devoured in the world, an idol teaches the shape. The module gives one to every
-- Devourer that has no shape yet.
DELETE FROM `item_template` WHERE `entry` IN (9100100, 9100101);
